"""Render the public complete-course syllabus from the authored curriculum."""
from html import escape as e
from pathlib import Path
import re
import json

def render(course, sources, projects):
    def li(text): return '<li>'+e(text)+'</li>'
    title=course['title']
    phases=[]
    for start,end,label,description in [
        (0,21,'Stage 1 · Legal foundations','Build the core concepts, research methods and first four portfolio projects. The foundation midterm and examination check this stage.'),
        (21,42,'Stage 2 · Applied law and professional skills','Return to the same 20 subjects through deeper problems, drafting and practice. Complete four further projects, the 40-question applied midterm and the 60-question comprehensive final.')]:
        modules=[]
        for index,m in enumerate(course['modules'][start:end],start+1):
            topics=[re.sub(r'^\d+\.\d+\s+','',l['t']) for l in m['lessons'] if not l.get('isQuiz')]
            quizsteps=[l for l in m['lessons'] if l.get('isQuiz')]
            footer=str(len(m['lessons']))+' learning steps · '+str(len(quizsteps))+' quizzes or examinations'
            modules.append('<details class="module"><summary><span class="num">'+str(index).zfill(2)+'</span>'+e(m['title'].split(': ',1)[1])+'<span class="plus" aria-hidden="true">+</span></summary><ul>'+''.join(li(t) for t in topics)+'</ul><p class="module-foot">'+e(footer)+'</p></details>')
        phases.append('<div class="section-head"><h3>'+label+'</h3><p>'+description+'</p></div><div class="modules">'+''.join(modules)+'</div>')
    project_cards=''.join('<article class="project"><h3>'+str(i+1)+'. '+e(t)+'</h3><p>'+e(s)+'</p><ul>'+''.join(li(d) for d in ds)+'</ul></article>' for i,(t,s,ds) in enumerate(projects))
    readings=''.join('<li><a href="'+e(url,quote=True)+'" target="_blank" rel="noopener noreferrer">'+e(label)+'</a></li>' for label,url in sources.values())
    faqs=[
        ('Who is this complete course for?','Learners seeking a structured study of Liberian law, prospective and current law students, community educators and professionals. The programme starts with foundations and progresses to applied analysis. It requires careful reading, writing and independent research.'),
        ('How is the programme connected to Liberian law schools?','Its subject coverage draws on published Liberian law-school areas of study and Liberian primary sources. It is an independent TIH course. It is not an official degree programme, institutional partnership, accredited law qualification or permission to practise law.'),
        ('What must I complete to earn the certificate?','Complete all 212 steps in order, including 80 taught lessons, their practice quizzes, 40 module assessments, both stage examinations and the applied midterm, all eight portfolio projects, and the 60-question programme final. Quizzes use the existing 70% pass threshold. Portfolio work is self-recorded using the supplied rubrics; tutor marking is not promised unless separately arranged.'),
        ('What happens to my earlier foundation progress?','The original 106 foundation steps stay in the same positions and their question banks stay unchanged. Completed foundation work remains recorded. The former final is now the foundation examination. It does not complete the expanded programme; the applied stage and new programme final are still required. Existing foundation credentials are not converted into the new credential.'),
        ('How long does the complete course take?','Plan about 160 hours. One suggested route is 32 weeks at five hours per week, or 16 weeks at ten hours per week. Prepare portfolio work throughout both stages. Longer seminars, legal research and revision can take more time; these are estimates, not completion deadlines.'),
        ('Are foreign video examples Liberian rules?','Some videos are comparative. Every lesson supplies a local reading or a verified source for the relevant framework. Check current Liberian statutes, regulations, court rules and judgments; do not import foreign deadlines, rates or procedures. Classroom scenarios are fictional and the programme is not personalised legal advice.')]
    faq_html=''.join('<details class="faq"><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>' for q,a in faqs)
    html='''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'''+e(title)+''' | TIH Learning Hub</title><meta name="description" content="A complete independent Liberian Law programme with 80 taught lessons, 42 modules, 460 distinct assessment questions and eight practical projects. Study foundations, applied law, research and advocacy."><link rel="canonical" href="https://tolbertinnovationhub.org/liberian-law"><link rel="stylesheet" href="liberian-law-page.css?v=1"><link rel="icon" href="favicon.svg"></head><body><a class="skip" href="#main">Skip to course content</a><header class="top"><div class="wrap"><a class="brand" href="learning-hub"><img src="assets/tih-logo.png" alt="Tolbert Innovation Hub">TIH Learning Hub</a><a class="back" href="learning-hub#tracks">All courses →</a></div></header><main id="main"><section class="hero"><div class="wrap"><div><p class="eyebrow">Law &amp; Governance · Foundations to applied study</p><h1>Complete<br><span>Liberian Law</span><br>Programme.</h1><p class="hero-copy">Study Liberia’s legal system, work through realistic classroom cases, and build your skills in research, drafting and advocacy. One complete course, from core concepts to a professional practice portfolio.</p><div class="actions"><a class="btn btn-red" href="hub-apply">Register · US$10</a><a class="btn btn-outline" href="#syllabus">Explore all 42 modules</a></div><p class="fine">Tuition is free. Registration is per course. Independent TIH education; Certificate of Completion.</p></div><img class="hero-art" src="liberian-law-card.svg?v=2" alt="Complete Liberian Law programme, TIH Learning Hub"></div></section><div class="stats"><div class="wrap"><div class="stat"><strong>80</strong><span>Taught lessons with full notes</span></div><div class="stat"><strong>460</strong><span>Distinct delivered questions</span></div><div class="stat"><strong>8</strong><span>Practical portfolio projects</span></div><div class="stat"><strong>160h</strong><span>Estimated study time</span></div></div></div><section><div class="wrap intro-grid"><div><h2>Understand the law. Practise the reasoning.</h2><p>Study 20 subject areas twice: first through foundations, then through applied legal problems. The programme contains 42 modules, 212 sequential learning steps and 124 quizzes and examinations.</p><ul class="outcomes">'''+''.join(li(t) for t in course['learn'])+'''</ul></div><aside class="callout"><h3>A complete TIH course</h3><p>Each taught lesson includes objectives, definitions, a substantive teaching explanation, a worked local classroom example, primary reading, key terms, review questions, activities and an assignment. Quizzes and examinations use distinct questions.</p><p>The final assesses all 20 law subjects. Your portfolio includes case briefs, memoranda, litigation files, due diligence, drafting and moot-court work.</p><p>This programme supports legal learning and law-school study. It does not award a law degree or professional practising authority.</p></aside></div></section><section class="curriculum" id="syllabus"><div class="wrap"><div class="section-head"><p class="eyebrow" style="color:#075985">The full course</p><h2>One programme. Two stages.</h2><p>Open a module to see its taught topics or project requirements. Learn in sequence, pass each quiz and retain the written assignments in your portfolio.</p></div>'''+''.join(phases)+'''</div></section><section><div class="wrap"><div class="section-head"><h2>Build an eight-project portfolio.</h2><p>Prepare work throughout the course. Each project includes deliverables, a weighted rubric and a completion checklist. Use fictional or appropriately handled public material.</p></div><div class="project-grid">'''+project_cards+'''</div></div></section><section class="reading"><div class="wrap"><h2>Read the sources that matter.</h2><p>Use the assigned text and check amendments, commencement and current local procedure. These links include Liberian primary materials and official research resources; comparative material does not replace local authority.</p><ul>'''+readings+'''</ul><p style="font-size:13px;color:#52657a">Subject-coverage reference: Liberia School of Law’s published study areas. No endorsement or affiliation is claimed. Sources reviewed 14 October 2026.</p></div></section><section><div class="wrap"><h2>Plan your study.</h2><p>Suggested pace: 32 weeks at five hours a week. Spend the first 16 weeks on foundations and the next 16 on applied study. Begin the project deliverables early, revise after each subject group, and allow extra time for longer seminars or research.</p>'''+faq_html+'''</div></section><section class="enrol"><div class="wrap"><div><h2>Begin the complete course.</h2><p>Create your account, confirm course access, and open “Complete Liberian Law Programme” from your dashboard.</p></div><div><a class="btn btn-red" href="hub-apply">Register · US$10</a><p><a href="course-player?id=liberian-law">Already enrolled? Open course →</a></p></div></div></section></main><footer><div class="wrap">© 2026 Tolbert Innovation Hub. <a href="learning-hub">Learning Hub</a> · <a href="contact">Contact TIH</a></div></footer></body></html>'''
    Path('liberian-law.html').write_text(html+'\n')
    blocks=[]
    for i,(first,last) in enumerate([(1,5),(6,10),(11,15),(16,21),(22,26),(27,31),(32,36),(37,42)]):
        blocks.append(dict(weeks=[i*4+1,i*4+4],modules=[first,last],estimatedHours=20,portfolioWork='Develop the stage portfolio throughout these weeks; the later project step records completion.'))
    Path('content/liberian-law-study-plan.json').write_text(json.dumps(dict(title=title,totalHours=160,suggestedWeeks=32,hoursPerWeek=5,blocks=blocks,scope='Suggested self-paced plan; longer seminars and research may require more time.'),ensure_ascii=False,indent=2)+'\n')
